`timescale 1ns/1ps

module tb_raytrace;

    // Shared constants generated by scene.py (FRAC_BITS, NUM_VERTS, NUM_TRIS, IMG_W, IMG_H)
    `include "C:/Users/khnay/Desktop/Ray/params.vh"

    reg [31:0] verts [0:NUM_VERTS*3-1];
    reg [31:0] tris  [0:NUM_TRIS*3-1];

    integer fd, i, p, last_pct, pct;

    // Prints a 20-char bar, e.g. [##########----------]  50%
    task print_bar;
        input integer percent;
        integer k;
        begin
            $write("Rendering   [");
            for (k = 0; k < 20; k = k + 1)
                if (k < percent / 5) $write("#"); else $write("-");
            $display("] %0d%%", percent);
        end
    endtask

    initial begin
        // 1. Load data exported by Python
        $readmemh("C:/Users/khnay/Desktop/Ray/verts.mem", verts);
        $readmemh("C:/Users/khnay/Desktop/Ray/tris.mem",  tris);

        // 2. Sanity check: unloaded memory would be X
        if (^verts[0] === 1'bx || ^tris[0] === 1'bx) begin
            $display("ERROR: .mem files did not load. Check the paths.");
            $finish;
        end
        $display("Loaded %0d vertices, %0d triangles, image %0dx%0d",
                 NUM_VERTS, NUM_TRIS, IMG_W, IMG_H);
        $display("verts[0..2] = %h %h %h", verts[0], verts[1], verts[2]);

        // 3. Echo the vertex and triangle data back out (Python will diff it)
        fd = $fopen("C:/Users/khnay/Desktop/Ray/data_echo.txt", "w");
        for (i = 0; i < NUM_VERTS*3; i = i + 1) $fdisplay(fd, "%08x", verts[i]);
        for (i = 0; i < NUM_TRIS*3;  i = i + 1) $fdisplay(fd, "%08x", tris[i]);
        $fclose(fd);

        // 4. Dummy render: every pixel = miss. Same format as golden.txt.
        fd = $fopen("C:/Users/khnay/Desktop/Ray/hw_out.txt", "w");
        last_pct = -1;
        for (p = 0; p < IMG_W*IMG_H; p = p + 1) begin
            $fdisplay(fd, "ffffffff 00000000");
            pct = ((p + 1) * 100) / (IMG_W*IMG_H);
            if (pct / 5 != last_pct / 5) begin   // print every 5%
                print_bar(pct);
                last_pct = pct;
            end
        end
        $fclose(fd);

        $display("Done. Wrote %0d pixels.", IMG_W*IMG_H);
        $finish;
    end

endmodule